#!/usr/bin/env node
'use strict';

const fs = require('fs');
const path = require('path');

function parseNativeOutput(sourceFile) {
  if (!fs.existsSync(sourceFile)) {
    throw new Error(`Native test output not found: ${sourceFile}`);
  }
  
  const content = fs.readFileSync(sourceFile, 'utf8');
  
  // In a production environment, this would parse real XML/JSON from XCTest/Detox/Espresso.
  // For the DesignOS orchestrator, we parse a structured JSON manifest generated by our native bridges.
  let report;
  try {
    report = JSON.parse(content);
  } catch (err) {
    throw new Error('Native output must be a valid JSON bridge manifest.');
  }
  
  return report;
}

function analyzeNativeEvidence(report) {
  const violations = [];
  
  const { 
    platform, 
    engine, 
    frames = [], 
    haptics = [], 
    thermalState,
    dynamicTypeScale,
    layout = {}
  } = report;
  
  // 1. Frame Pacing (Jitter in 60/120hz)
  // A frame on 60hz should take ~16.6ms. We check for dropped frames (duration > 33ms).
  const droppedFrames = frames.filter(f => f.durationMs > 33);
  if (droppedFrames.length > 0) {
    violations.push({
      type: 'frame-pacing',
      message: `Detected ${droppedFrames.length} dropped frame(s) exceeding 33ms (jitter). Native motion requires strict pacing.`,
      severity: 'high'
    });
  }
  
  // 2. Haptic Verification
  // If gestures like 'swipe' or 'longPress' are in the timeline, ensure CoreHaptics fired.
  if (report.gestures && report.gestures.length > 0) {
    if (haptics.length === 0) {
      violations.push({
        type: 'haptic-verification',
        message: 'Gesture interaction executed but no OS-level haptic feedback was triggered.',
        severity: 'medium'
      });
    }
  }
  
  // 3. Thermal Throttling
  // Native motion shouldn't execute complex physical simulations if battery is low or device is hot.
  if (thermalState === 'serious' || thermalState === 'critical') {
    if (report.animationsActive) {
      violations.push({
        type: 'thermal-throttling',
        message: `Device thermal state is '${thermalState}', but animations were not aggressively reduced.`,
        severity: 'high'
      });
    }
  }
  
  // 4. Dynamic Type
  if (dynamicTypeScale > 1.5) {
    if (layout.textClipped || layout.boundsOverflow) {
      violations.push({
        type: 'dynamic-type',
        message: `Layout bounds overflowed or clipped at OS text scale ${dynamicTypeScale}x.`,
        severity: 'high'
      });
    }
  }
  
  // 5. Safe Area & Keyboard Insets
  if (layout.keyboardVisible) {
    if (layout.focusedElementY > layout.keyboardY) {
      violations.push({
        type: 'safe-area-inset',
        message: 'Focused element is obscured by the virtual keyboard inset.',
        severity: 'high'
      });
    }
  }
  
  // 6. Back Gesture / Cancellation
  if (report.gestures && report.gestures.some(g => g.type === 'edge-swipe')) {
    const cancelled = report.gestures.find(g => g.type === 'edge-swipe' && g.cancelled);
    if (cancelled && !cancelled.stateRestored) {
      violations.push({
        type: 'gesture-cancellation',
        message: 'Edge back-gesture was cancelled mid-flight, but the view state was not seamlessly restored.',
        severity: 'high'
      });
    }
  }
  
  return {
    schema: 1,
    platform,
    engine,
    passed: violations.length === 0,
    violations
  };
}

function main() {
  const args = process.argv.slice(2);
  const target = args.find(arg => !arg.startsWith('--'));
  if (!target) throw new Error('Usage: native-evidence-lab <mock-xctest-output.json>');
  
  console.log(`Starting Native Device Evidence Lab...`);
  
  const report = parseNativeOutput(path.resolve(target));
  console.log(`- Platform: ${report.platform}`);
  console.log(`- Engine: ${report.engine}`);
  
  const analysis = analyzeNativeEvidence(report);
  
  if (analysis.passed) {
    console.log(`\n✅ Native Source Conformance Verified!`);
    process.exit(0);
  } else {
    console.log(`\n❌ Native Conformance Failures (${analysis.violations.length}):`);
    analysis.violations.forEach(v => {
      console.log(`  [${v.type.toUpperCase()}] ${v.message}`);
    });
    process.exit(1);
  }
}

if (require.main === module) main().catch(err => { console.error(err.message); process.exit(1); });
module.exports = { analyzeNativeEvidence };
